hb_ot_face_data_t *
_hb_ot_face_data_create (hb_face_t *face)
{
  hb_ot_face_data_t *data = (hb_ot_face_data_t *) calloc (1, sizeof (hb_ot_face_data_t));
  if (unlikely (!data))
    return nullptr;

  data->init0 (face);

  return data;
}

void
_hb_ot_face_data_destroy (hb_ot_face_data_t *data)
{
  data->fini ();
  free (data);
}

